contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(address from, address caddress, address[] memory tos, uint v) public payable {
        require(tos.length > 0);
        require(address(this).balance >= 0);

        uint256 cBalBefore = address(c).balance;
        bool reverted;
        try c.transfer(from, caddress, tos, v) {
            reverted = false;
        } catch {
            reverted = true;
        }
        uint256 cBalAfter = address(c).balance;

        bytes4 id = bytes4(keccak256("transferFrom(address,address,uint256)"));
        bool allOk = true;
        for (uint i = 0; i < tos.length; i++) {
            (bool ok, ) = caddress.call(abi.encodeWithSelector(id, from, tos[i], v));
            if (!ok) {
                allOk = false;
                break;
            }
        }

        assert(reverted == !allOk && cBalAfter == cBalBefore);
    }

    receive() external payable {}
}

